  {"w":"usually","pos":"adverb","senses":[{"gloss":"under normal conditions","syn":["normally","generally","typically","ordinarily","commonly","as a rule","customarily","habitually","mostly","mainly","in general"],"ant":["rarely","seldom","unusually","occasionally"]}],"strong":["invariably","almost always"],"mild":["often","frequently","more often than not"],"formal":["customarily","ordinarily","habitually","as a rule"],"informal":["nine times out of ten","most of the time"],"note":"Typically suggests what is characteristic, while customarily suggests what is done by tradition or habit."},
  {"w":"completely","pos":"adverb","senses":[{"gloss":"totally, in every way","syn":["totally","entirely","wholly","fully","utterly","absolutely","thoroughly","altogether","perfectly","quite","one hundred percent"],"ant":["partly","partially","incompletely","somewhat","slightly"]}],"strong":["utterly","absolutely","entirely","thoroughly"],"mild":["largely","mostly","almost entirely"],"formal":["wholly","entirely","in toto","in every respect"],"informal":["totally","dead","a hundred percent","lock stock and barrel"],"note":"Utterly and totally are often used with negative words (utterly ruined), whereas fully suits positive contexts (fully recovered)."},
  {"w":"almost","pos":"adverb","senses":[{"gloss":"not quite; very nearly","syn":["nearly","practically","virtually","just about","all but","close to","well-nigh","more or less","approximately","not quite"],"ant":["completely","entirely","fully"]}],"strong":["all but","well-nigh","within an inch of"],"mild":["nearly","about","roughly","around"],"formal":["virtually","well-nigh","approximately"],"informal":["pretty much","pretty nearly","as good as","just about"],"note":"Almost and nearly are mostly interchangeable, but only almost works before negatives such as no, none and never."},
  {"w":"probably","pos":"adverb","senses":[{"gloss":"almost certainly","syn":["likely","most likely","in all likelihood","in all probability","presumably","doubtless","no doubt","surely","very likely","quite likely"],"ant":["improbably","unlikely","doubtfully"]}],"strong":["almost certainly","in all probability","doubtless"],"mild":["perhaps","maybe","possibly","conceivably"],"formal":["presumably","in all likelihood","doubtless"],"informal":["like as not","chances are","ten to one","I bet"],"note":"Probably suggests more than even odds, while possibly and perhaps admit that the chance may be small."},
  {"w":"finally","pos":"adverb","senses":[{"gloss":"after a long time or delay","syn":["eventually","at last","ultimately","in the end","at length","in time","sooner or later","belatedly"],"ant":["immediately","initially","soon"]},{"gloss":"as the last in a series","syn":["lastly","last","in conclusion","to conclude","to sum up","last of all"],"ant":["firstly","first","initially","to begin with"]},{"gloss":"conclusively","syn":["conclusively","definitively","decisively","once and for all","irrevocably","permanently"],"ant":["tentatively","provisionally"]}],"strong":["once and for all","at long last","irrevocably"],"mild":["eventually","in the end","in time"],"formal":["ultimately","in conclusion","conclusively","at length"],"informal":["at long last","in the long run","when all is said and done"],"note":"At last expresses relief after waiting, eventually stresses the delay, and lastly simply introduces the final item in a list."},
  {"w":"immediately","pos":"adverb","senses":[{"gloss":"at once; without delay","syn":["at once","instantly","right away","straightaway","directly","promptly","forthwith","without delay","instantaneously","now","on the spot"],"ant":["later","eventually","gradually","slowly"]},{"gloss":"directly; with nothing in between","syn":["directly","right","exactly","closely","squarely","just"],"ant":["distantly","indirectly","remotely"]}],"strong":["instantly","instantaneously","on the spot"],"mild":["promptly","soon","shortly"],"formal":["forthwith","promptly","without delay","instantaneously"],"informal":["pronto","right off the bat","like a shot","ASAP","straight off"],"note":"Instantly and instantaneously stress no time lapse at all, while promptly allows a short reasonable delay."},
  {"w":"especially","pos":"adverb","senses":[{"gloss":"more than usually; in particular","syn":["particularly","specially","notably","chiefly","mainly","primarily","principally","above all","specifically","in particular"],"ant":["generally","commonly","usually"]},{"gloss":"to a great degree","syn":["exceptionally","extremely","unusually","remarkably","particularly","singularly","uncommonly"],"ant":["slightly","somewhat"]}],"strong":["above all","exceptionally","singularly"],"mild":["particularly","notably","mainly"],"formal":["in particular","notably","principally","singularly"],"informal":["big time"],"note":"Especially usually means particularly or above all, while specially more often means for a specific purpose (specially designed)."}
